update public.content_variants set body = $json${"text":"Mr Budi's family in Surabaya makes a monthly budget by first setting aside IDR 1 million for savings for their children's education, then managing other expenses. The principle of \"pay yourself first\" helps them consistently save.","source_ids":["7f4b83f2-8f1d-415c-9d4f-64e6284bef04"]}$json$::jsonb where id = 'e1d15afb-5d2b-4651-a0ce-d2847e65ca0d';
