update public.content_variants set body_id = $json${"type":"image_interpretation","answer":"Saham secara historis melampaui inflasi","options":["Rekening tabungan mengalahkan inflasi","Saham secara historis melampaui inflasi","Semua investasi adalah sama","Uang tunai adalah penyimpan nilai terbaik"],"question":"[GAMBAR: Diagram batang yang membandingkan tingkat inflasi (3%) vs bunga rekening tabungan (2%) vs rata-rata pengembalian pasar saham (10%) selama 10 tahun.]\n\nWawasan penting apa yang diungkapkan oleh perbandingan ini?","difficulty":"intermediate","parameters":{"image_description":"A bar chart comparing inflation rate (3%) vs savings account interest (2%) vs stock market average return (10%) over 10 years."},"explanation":"Grafik tersebut menunjukkan bahwa meskipun tabungan kehilangan daya beli karena inflasi, ekuitas secara historis memberikan keuntungan yang melebihi inflasi."}$json$::jsonb where id = 'e4e6929b-322e-4a09-8ecc-4f7deeb4f553';
update public.content_variants set body_id = $json${"type":"spot_mistake","answer":["Membawa saldo kartu kredit yang tinggi","Hanya membayar minimum","Menggunakan pulsa untuk pembelian rutin tanpa rencana","Akumulasi bunga bulanan 2,5%."],"options":["Membawa saldo kartu kredit yang tinggi","Hanya membayar minimum","Menggunakan pulsa untuk pembelian rutin tanpa rencana","Akumulasi bunga bulanan 2,5%.","Tidak ada kesalahan","Hanya satu kesalahan kecil"],"question":"Bacalah pernyataan berikut dan kenali kesalahan finansialnya:\n\nSaya menggunakan kartu kredit saya untuk semua pembelian karena saya mendapatkan cashback. Saya hanya membayar saldo minimum setiap bulannya. Saya mempunyai utang kartu kredit sebesar Rp 50 juta.","difficulty":"advanced","parameters":{"mistake_count":4},"explanation":"Utang kartu kredit sebesar 2,5% setiap bulannya bertambah ke tingkat yang sangat buruk. Pembayaran minimum memperpanjang hutang selama bertahun-tahun."}$json$::jsonb where id = 'e4ff7e2b-04b1-4be0-8051-3dae5efecfc9';
update public.content_variants set body_id = $json${"type":"comparison","answer":"Rata-rata biaya dolar","options":["Investasi sekaligus","Rata-rata biaya dolar","Keduanya menghilangkan risiko waktu","Tidak ada yang membantu"],"question":"Bandingkan investasi sekaligus dengan rata-rata biaya dolar (DCA) di pasar yang bergejolak. Mana yang biasanya mengurangi risiko waktu?","difficulty":"intermediate","parameters":{},"explanation":"DCA menyebarkan pembelian dari waktu ke waktu, mengurangi dampak investasi pada puncak pasar."}$json$::jsonb where id = 'e51ea97f-8dee-47e7-a4b5-147d4d54a5aa';
